// Turn each downloaded page into clean lines of text for the change monitor
const pages = $('Competitor pages').all();
const settings = $('Settings').first().json;

const hash = s => {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return h.toString(36);
};
const decode = s => s
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));

const out = [];
$input.all().forEach((item, i) => {
  const page = pages[i]?.json || {};
  const url = String(page.url || '').trim();
  if (!url) return;
  const html = String(item.json.html || '');
  const lines = decode(
    html
      .replace(/<(script|style|noscript|svg|template|iframe)[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<\/?(br|p|div|li|h[1-6]|tr|td|th|section|article|header|footer|nav|ul|ol|table|title|main|aside|form|button|dd|dt|option|label)\b[^>]*>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
  )
    .split('\n')
    .map(l => l.replace(/\s+/g, ' ').trim())
    .filter(l => l.length >= 2 && l.length <= 600);
  const unique = [...new Set(lines)].slice(0, 1500);

  // Pages that failed or came back almost empty are skipped, so they are not reported as "everything removed"
  if (unique.length < 5) return;

  out.push({
    json: {
      name: page.name || url,
      url,
      lineCount: unique.length,
      actorInput: {
        monitorName: `${settings.monitorPrefix || 'competitor-pages'}-${hash(url)}`,
        // context = the two lines above, so a changed price still shows which plan it belongs to
        items: unique.map((text, n) => ({ line: text, context: unique.slice(Math.max(0, n - 2), n).join(' / ') })),
        idFields: ['line'],
        reportNew: true,
        trackRemoved: true,
        reportChanged: false,
        detailedDiff: true,
      },
    },
  });
});
return out;

// Group the added and removed lines by page
const pages = new Map(
  $('Split into text blocks').all().map(p => [p.json.actorInput.monitorName, p.json])
);
const byPage = new Map();
for (const { json: c } of $input.all()) {
  if (!c.changeType || !pages.has(c.monitorName)) continue;
  const page = pages.get(c.monitorName);
  if (!byPage.has(page.url)) byPage.set(page.url, { name: page.name, url: page.url, added: [], removed: [] });
  const line = { text: c.key || c.item?.line || '', context: c.item?.context || '' };
  if (c.changeType === 'new') byPage.get(page.url).added.push(line);
  if (c.changeType === 'removed') byPage.get(page.url).removed.push(line);
}
return [...byPage.values()].map(p => ({ json: p }));

// Put the screenshot link next to each changed page
const pages = $('Group changes by page').all();
const shots = $input.all();
return pages.map((p, i) => {
  const shot = shots[i]?.json || {};
  const clip = list => list.slice(0, 60)
    .map(l => '- ' + l.text.slice(0, 300) + (l.context ? `  [below: ${l.context.slice(0, 150)}]` : ''))
    .join('\n') || '(none)';
  return {
    json: {
      ...p.json,
      screenshotUrl: shot.screenshotUrl || '',
      addedText: clip(p.json.added),
      removedText: clip(p.json.removed),
    },
  };
});

