// Keep important changes (or all of them if onlyImportant is false)
const pages = $('Attach screenshot').all();
const onlyImportant = $('Settings').first().json.onlyImportant !== false;
return $input.all()
  .map((item, i) => {
    const r = item.json.output || {};
    const p = pages[i].json;
    return {
      json: {
        date: new Date().toISOString().slice(0, 10),
        name: p.name,
        url: p.url,
        important: r.important !== false,
        category: r.category || 'other',
        summary: r.summary || '',
        details: (r.changes || []).join('\n'),
        linesAdded: p.added.length,
        linesRemoved: p.removed.length,
        screenshotUrl: p.screenshotUrl,
      },
    };
  })
  .filter(x => !onlyImportant || x.json.important);
